from __future__ import annotations

import argparse
import json
import shutil
import subprocess
from dataclasses import asdict, dataclass
from pathlib import Path


REPO_ROOT = Path(__file__).resolve().parent.parent
ENV_FILE = REPO_ROOT / ".op" / "openrouter.env"
RESOLVER_PY = REPO_ROOT / "!" / "resolve_openrouter_secret.py"
RESOLVER_PS1 = REPO_ROOT / "!" / "resolve-openrouter-secret.ps1"
RUNTIME_SCRIPT = REPO_ROOT / "scripts" / "openrouter_runtime.py"
LAUNCHER_PATHS = (
    REPO_ROOT / "scripts" / "Start-CodexOpenRouter.ps1",
    REPO_ROOT / "scripts" / "Start-ClaudeOpenRouter.ps1",
    REPO_ROOT / "!" / "launch-codex-openrouter.cmd",
    REPO_ROOT / "!" / "launch-claude-openrouter.cmd",
)


@dataclass(frozen=True)
class ValidationResult:
    name: str
    ok: bool
    severity: str
    detail: str


def parse_env_file(path: Path) -> dict[str, str]:
    values: dict[str, str] = {}
    if not path.exists():
        return values
    for raw_line in path.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        values[key.strip()] = value.strip()
    return values


def normalize_env_aliases(values: dict[str, str]) -> dict[str, str]:
    normalized = values.copy()
    if not normalized.get("OPENROUTER_API_KEY") and normalized.get("OPENAI_API_KEY"):
        normalized["OPENROUTER_API_KEY"] = normalized["OPENAI_API_KEY"]
    if not normalized.get("OPENAI_API_KEY") and normalized.get("OPENROUTER_API_KEY"):
        normalized["OPENAI_API_KEY"] = normalized["OPENROUTER_API_KEY"]
    if not normalized.get("ANTHROPIC_AUTH_TOKEN") and normalized.get("ANTHROPIC_API_KEY"):
        normalized["ANTHROPIC_AUTH_TOKEN"] = normalized["ANTHROPIC_API_KEY"]
    if not normalized.get("ANTHROPIC_API_KEY") and normalized.get("ANTHROPIC_AUTH_TOKEN"):
        normalized["ANTHROPIC_API_KEY"] = normalized["ANTHROPIC_AUTH_TOKEN"]
    if not normalized.get("OPENAI_BASE_URL"):
        normalized["OPENAI_BASE_URL"] = "https://openrouter.ai/api/v1"
    if not normalized.get("ANTHROPIC_BASE_URL"):
        normalized["ANTHROPIC_BASE_URL"] = "https://openrouter.ai/api"
    return normalized


def _check_path_exists(name: str, path: Path) -> ValidationResult:
    return ValidationResult(
        name=name,
        ok=path.exists(),
        severity="error",
        detail=f"{path.relative_to(REPO_ROOT)} {'present' if path.exists() else 'missing'}",
    )


def _check_op_status() -> ValidationResult:
    if shutil.which("op") is None:
        return ValidationResult(
            name="1Password CLI",
            ok=False,
            severity="warn",
            detail="`op` is not on PATH; local fallback depends on .op/openrouter.env.",
        )
    result = subprocess.run(
        ["op", "whoami"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
    )
    if result.returncode == 0:
        return ValidationResult(
            name="1Password CLI",
            ok=True,
            severity="info",
            detail="`op whoami` succeeded.",
        )
    return ValidationResult(
        name="1Password CLI",
        ok=False,
        severity="warn",
        detail="`op` is installed but not signed in; env-file fallback is required.",
    )


def validate_openrouter_env() -> list[ValidationResult]:
    results = [
        _check_path_exists("Resolver (Python)", RESOLVER_PY),
        _check_path_exists("Resolver (PowerShell)", RESOLVER_PS1),
        _check_path_exists("Runtime launcher", RUNTIME_SCRIPT),
    ]
    results.extend(_check_path_exists(f"Launcher `{path.name}`", path) for path in LAUNCHER_PATHS)
    results.append(_check_path_exists("OpenRouter env file", ENV_FILE))
    results.append(_check_op_status())

    env_values = normalize_env_aliases(parse_env_file(ENV_FILE))
    required_keys = {
        "OPENROUTER_API_KEY": "OpenRouter API key ref/value",
        "OPENAI_API_KEY": "OpenAI compatibility key ref/value",
        "OPENAI_BASE_URL": "OpenAI compatibility base URL",
        "ANTHROPIC_AUTH_TOKEN": "Anthropic compatibility auth token ref/value",
        "ANTHROPIC_BASE_URL": "Anthropic compatibility base URL",
        "ANTHROPIC_API_KEY": "Anthropic compatibility API key ref/value",
    }

    for key, description in required_keys.items():
        value = env_values.get(key, "")
        results.append(
            ValidationResult(
                name=f"Env key `{key}`",
                ok=bool(value),
                severity="error",
                detail=f"{description} {'present' if value else 'missing'}",
            )
        )

    if env_values:
        openai_base_url = env_values.get("OPENAI_BASE_URL")
        results.append(
            ValidationResult(
                name="OpenAI base URL",
                ok=openai_base_url == "https://openrouter.ai/api/v1",
                severity="error",
                detail=f"expected `https://openrouter.ai/api/v1`, got `{openai_base_url or '<missing>'}`",
            )
        )
        anthropic_base_url = env_values.get("ANTHROPIC_BASE_URL")
        results.append(
            ValidationResult(
                name="Anthropic base URL",
                ok=anthropic_base_url == "https://openrouter.ai/api",
                severity="error",
                detail=f"expected `https://openrouter.ai/api`, got `{anthropic_base_url or '<missing>'}`",
            )
        )

        for key in ("OPENROUTER_API_KEY", "OPENAI_API_KEY", "ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_API_KEY"):
            value = env_values.get(key, "")
            if value.startswith("sk-"):
                results.append(
                    ValidationResult(
                        name=f"Secret style `{key}`",
                        ok=False,
                        severity="warn",
                        detail="plaintext key detected; prefer `op://...` references for local env files.",
                    )
                )
            elif value.startswith("op://"):
                results.append(
                    ValidationResult(
                        name=f"Secret style `{key}`",
                        ok=True,
                        severity="info",
                        detail="uses a 1Password item reference.",
                    )
                )

        if any(env_values.get(key, "").startswith("op://") for key in required_keys):
            op_available = shutil.which("op") is not None and subprocess.run(
                ["op", "whoami"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=False,
            ).returncode == 0
            results.append(
                ValidationResult(
                    name="Env-file fallback",
                    ok=op_available or all(
                        not env_values.get(key, "").startswith("op://") for key in required_keys
                    ),
                    severity="warn" if not op_available else "info",
                    detail=(
                        "1Password resolution is available for this env file."
                        if op_available
                        else "env file contains unresolved `op://...` references and requires 1Password resolution."
                    ),
                )
            )

    return results


def render_markdown(results: list[ValidationResult]) -> str:
    lines = [
        "# OpenRouter Runtime Validation",
        "",
        "| Check | Status | Severity | Detail |",
        "| --- | --- | --- | --- |",
    ]
    for result in results:
        status = "OK" if result.ok else "FAIL"
        lines.append(f"| {result.name} | `{status}` | `{result.severity}` | {result.detail} |")
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description="Validate the local OpenRouter runtime contract.")
    parser.add_argument("--format", choices=("markdown", "json"), default="markdown")
    args = parser.parse_args()

    results = validate_openrouter_env()
    if args.format == "json":
        print(json.dumps([asdict(result) for result in results], indent=2))
    else:
        print(render_markdown(results))

    hard_failures = [result for result in results if result.severity == "error" and not result.ok]
    return 0 if not hard_failures else 1


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import argparse
import os
import shutil
import subprocess
import sys
from pathlib import Path


REPO_ROOT = Path(__file__).resolve().parent.parent
ENV_FILE = REPO_ROOT / ".op" / "openrouter.env"
RESOLVER = REPO_ROOT / "!" / "resolve_openrouter_secret.py"


def ensure_dir(path: Path) -> Path:
    path.mkdir(parents=True, exist_ok=True)
    return path.resolve()


def apply_runtime_env(agent: str) -> dict[str, str]:
    env = os.environ.copy()

    shared_paths = {
        "TMP": REPO_ROOT / ".tmp",
        "TEMP": REPO_ROOT / ".tmp",
        "TMPDIR": REPO_ROOT / ".tmp",
        "UV_CACHE_DIR": REPO_ROOT / ".uv-cache",
        "PIP_CACHE_DIR": REPO_ROOT / ".pip-cache",
        "NPM_CONFIG_CACHE": REPO_ROOT / ".npm-cache",
        "XDG_CACHE_HOME": REPO_ROOT / ".cache",
        "XDG_STATE_HOME": REPO_ROOT / ".state",
        "PYTHONPYCACHEPREFIX": REPO_ROOT / ".pycache",
    }

    for name, path in shared_paths.items():
        env[name] = str(ensure_dir(path))

    agent_home_root = ensure_dir(REPO_ROOT / ".agent-home")

    if agent == "codex":
        env["CODEX_HOME"] = str(ensure_dir(agent_home_root / "codex"))
    elif agent == "claude":
        env["APPDATA"] = str(ensure_dir(agent_home_root / "claude" / "AppData" / "Roaming"))
        env["LOCALAPPDATA"] = str(ensure_dir(agent_home_root / "claude" / "AppData" / "Local"))

    return env


def ensure_op_available() -> None:
    if shutil.which("op") is None:
        raise SystemExit(
            "1Password CLI 'op' is not installed or not on PATH.\n"
            "If .op/openrouter.env exists, you can use the env file directly."
        )


def ensure_op_signed_in() -> None:
    result = subprocess.run(
        ["op", "whoami"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
    )
    if result.returncode != 0:
        raise SystemExit(
            "1Password CLI is not signed in. Run 'op signin' or unlock desktop integration.\n"
            "If .op/openrouter.env exists, you can use the env file directly."
        )


def parse_env_content(content: str) -> dict[str, str]:
    values: dict[str, str] = {}
    for raw_line in content.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        values[key.strip()] = value.strip()
    return values


def normalize_env_aliases(values: dict[str, str]) -> dict[str, str]:
    normalized = values.copy()

    if not normalized.get("OPENROUTER_API_KEY") and normalized.get("OPENAI_API_KEY"):
        normalized["OPENROUTER_API_KEY"] = normalized["OPENAI_API_KEY"]
    if not normalized.get("OPENAI_API_KEY") and normalized.get("OPENROUTER_API_KEY"):
        normalized["OPENAI_API_KEY"] = normalized["OPENROUTER_API_KEY"]

    if not normalized.get("ANTHROPIC_AUTH_TOKEN") and normalized.get("ANTHROPIC_API_KEY"):
        normalized["ANTHROPIC_AUTH_TOKEN"] = normalized["ANTHROPIC_API_KEY"]
    if not normalized.get("ANTHROPIC_API_KEY") and normalized.get("ANTHROPIC_AUTH_TOKEN"):
        normalized["ANTHROPIC_API_KEY"] = normalized["ANTHROPIC_AUTH_TOKEN"]

    if not normalized.get("OPENAI_BASE_URL"):
        normalized["OPENAI_BASE_URL"] = "https://openrouter.ai/api/v1"
    if not normalized.get("OPENAI_MODEL"):
        normalized["OPENAI_MODEL"] = "openrouter/auto"
    if not normalized.get("ANTHROPIC_BASE_URL"):
        normalized["ANTHROPIC_BASE_URL"] = "https://openrouter.ai/api"

    return normalized


def load_env_file_values(path: Path) -> dict[str, str]:
    if not path.exists():
        return {}
    return normalize_env_aliases(parse_env_content(path.read_text(encoding="utf-8")))


def env_contains_unresolved_refs(values: dict[str, str], keys: list[str]) -> bool:
    return any(values.get(key, "").startswith("op://") for key in keys)


def ensure_env_file(agent: str) -> Path:
    required_keys = {
        "codex": ["OPENAI_API_KEY", "OPENAI_BASE_URL"],
        "claude": ["ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_BASE_URL", "ANTHROPIC_API_KEY"],
    }[agent]

    needs_refresh = not ENV_FILE.exists()
    if not needs_refresh:
        env_values = parse_env_content(ENV_FILE.read_text(encoding="utf-8"))
        needs_refresh = any(not env_values.get(key) for key in required_keys)

    if needs_refresh:
        if shutil.which("op") is None:
            raise SystemExit(
                f"Env file missing or incomplete and 1Password CLI not available.\n"
                f"Please create {ENV_FILE} with your OpenRouter API key."
            )
        subprocess.run([sys.executable, str(RESOLVER)], check=True)

    return ENV_FILE


def exec_agent(agent: str, cli_name: str, args: list[str], env_overrides: dict[str, str] | None = None) -> int:
    env = apply_runtime_env(agent)
    if env_overrides:
        env.update(env_overrides)
    resolved_cli = shutil.which(cli_name, path=env.get("PATH"))
    if resolved_cli is None:
        raise SystemExit(f"Could not find '{cli_name}' on PATH.")

    result = subprocess.run([resolved_cli, *args], env=env, check=False)
    return result.returncode


def is_help_request(args: list[str]) -> bool:
    return any(arg in {"-h", "--help"} for arg in args)


def launch_agent(agent: str, cli_name: str, args: list[str]) -> int:
    if agent not in {"codex", "claude"}:
        raise SystemExit(f"Unsupported OpenRouter agent: {agent}")

    if is_help_request(args):
        return exec_agent(agent, cli_name, args)

    env_file = ensure_env_file(agent)

    if shutil.which("op") is not None:
        result = subprocess.run(["op", "whoami"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
        if result.returncode == 0:
            command = [
                "op",
                "run",
                f"--env-file={env_file}",
                "--",
                sys.executable,
                str(Path(__file__).resolve()),
                "--exec",
                agent,
                cli_name,
                *args,
            ]
            result = subprocess.run(command, check=False)
            return result.returncode

    env_values = load_env_file_values(env_file)
    required_keys = {
        "codex": ["OPENAI_API_KEY", "OPENAI_BASE_URL"],
        "claude": ["ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_BASE_URL", "ANTHROPIC_API_KEY"],
    }[agent]
    if env_contains_unresolved_refs(env_values, required_keys):
        raise SystemExit(
            "OpenRouter env-file fallback is not usable without 1Password resolution.\n"
            f"Resolve {env_file} with `op run` or replace its `op://...` refs with concrete values."
        )

    return exec_agent(agent, cli_name, args, env_overrides=env_values or None)


def main() -> int:
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("--exec", dest="exec_mode", action="store_true")
    parser.add_argument("agent")
    parser.add_argument("cli_name")
    parser.add_argument("args", nargs="*")
    parsed = parser.parse_args()

    if parsed.exec_mode:
        return exec_agent(parsed.agent, parsed.cli_name, parsed.args)

    return launch_agent(parsed.agent, parsed.cli_name, parsed.args)


if __name__ == "__main__":
    raise SystemExit(main())

